'use strict';

// MODULES //

import getOrder from '@stdlib/ndarray-base-order';
import defaults from '@stdlib/ndarray-defaults';


// VARIABLES //

var DEFAULT_ORDER = defaults.get( 'order' );


// MAIN //

/**
* Resolves the order (i.e. memory layout) of an output ndarray according to a list of input ndarrays.
*
* @param {ArrayLikeObject<ndarrayLike>} arrays - list of input ndarrays
* @returns {string} storage layout
*
* @example
* import zeros from '@stdlib/ndarray-zeros';
*
* var x = zeros( [ 2, 2 ] );
* var y = zeros( [ 2, 2 ] );
*
* var order = outputOrder( [ x, y ] );
* // returns <string>
*/
function outputOrder( arrays ) {
	var N;
	var o;
	var i;

	N = arrays.length;
	if ( N === 0 ) {
		return DEFAULT_ORDER;
	}
	// Resolve the order of the first ndarray:
	o = getOrder( arrays[ 0 ] );

	// If a subsequent input ndarray has a different order, return the default memory layout...
	for ( i = 1; i < N; i++ ) {
		if ( getOrder( arrays[ i ] ) !== o ) {
			return DEFAULT_ORDER;
		}
	}
	return o;
}


// EXPORTS //

export default outputOrder;
